    """Fill zero cells by reflection across the horizontal midline."""
    out = [row[:] for row in grid]
    h = len(grid)
    for r in range(h):
        for c in range(len(grid[r])):
            if grid[r][c] == 0:
                rr = h - 1 - r
                if 0 <= rr < h and c < len(grid[rr]) and grid[rr][c] != 0:
                    out[r][c] = grid[rr][c]
    return out
